import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.dWYrTn1b.js";const h=JSON.parse(`{"title":"Architecture","description":"The compiler's repository layout, compilation flow and dependency boundaries; the design source of truth.","frontmatter":{"title":"Architecture","description":"The compiler's repository layout, compilation flow and dependency boundaries; the design source of truth."},"headers":[],"relativePath":"development/architecture.md","filePath":"development/architecture.md"}`),o={name:"development/architecture.md"};function i(r,e,p,l,c,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>RobotDSL-Core is a Python compiler. It checks robot, world, task, and evaluation descriptions together, then generates native files for the user&#39;s robot environment. ROS, simulators, and Docker are execution or test dependencies, not compiler dependencies.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>robotdsl-core/</span></span>
<span class="line"><span>├── pyproject.toml</span></span>
<span class="line"><span>├── src/mobiledsl/</span></span>
<span class="line"><span>│   ├── cli.py                 command-line entrypoint</span></span>
<span class="line"><span>│   ├── driver/                source loading, phase orchestration, output writing</span></span>
<span class="line"><span>│   ├── frontend/              grammar, parser, AST, source locations</span></span>
<span class="line"><span>│   ├── semantic/</span></span>
<span class="line"><span>│   │   ├── model/             vocabulary, resolved program, analysis facts; no AST dependency</span></span>
<span class="line"><span>│   │   ├── lower.py           name resolution, type checking, AST normalization</span></span>
<span class="line"><span>│   │   └── analysis/          physical assembly, requirements, and task dataflow</span></span>
<span class="line"><span>│   ├── validation/            rules over analysis facts</span></span>
<span class="line"><span>│   ├── library/               component and scene library loading</span></span>
<span class="line"><span>│   ├── support/               shared diagnostics and source-location types</span></span>
<span class="line"><span>│   └── targets/</span></span>
<span class="line"><span>│       ├── gazebo/            native models, physics, and simulated sensors</span></span>
<span class="line"><span>│       ├── mujoco/            the MuJoCo scene and the node that simulates it</span></span>
<span class="line"><span>│       ├── ros2/              ROS interfaces, control, launch, and runtime helpers</span></span>
<span class="line"><span>│       ├── nav2/              navigation providers and configuration</span></span>
<span class="line"><span>│       ├── mission/           the mission and evaluation data every runtime reads</span></span>
<span class="line"><span>│       ├── payload.py         the runtime files every target copies</span></span>
<span class="line"><span>│       ├── ros_gz_nav2/       composition for Gazebo and cross-adapter checks</span></span>
<span class="line"><span>│       └── ros_mujoco_nav2/   composition for MuJoCo</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>│   ├── architecture/          import and installation boundaries</span></span>
<span class="line"><span>│   ├── driver/</span></span>
<span class="line"><span>│   ├── frontend/</span></span>
<span class="line"><span>│   ├── semantic/</span></span>
<span class="line"><span>│   ├── validation/</span></span>
<span class="line"><span>│   ├── library/</span></span>
<span class="line"><span>│   ├── targets/               native-tool and simulation tests</span></span>
<span class="line"><span>│   └── library/fixtures/      the demo library the tests assemble robots from</span></span>
<span class="line"><span>├── docker/                    the test images&#39; build files</span></span>
<span class="line"><span>├── tools/                     development utilities</span></span>
<span class="line"><span>└── docs/                      this site (VitePress)</span></span></code></pre></div><p>Target packages own their binding, native-input adapters, typed output models, and emitters. <code>ros_gz_nav2</code> owns Gazebo–ROS integration and composes the launch plan; Gazebo and Nav2 do not import each other. Changing simulators reuses robot and task semantics and autonomy adapters; composition checks interface compatibility. Runtime helpers live with their owning adapter and execute in the target environment. Compiler code never imports those helpers or ROS/simulator SDKs.</p><h2 id="compilation-flow" tabindex="-1">Compilation flow <a class="header-anchor" href="#compilation-flow" aria-label="Permalink to &quot;Compilation flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>program source                  library directories</span></span>
<span class="line"><span>       │                                │</span></span>
<span class="line"><span>       ▼                                ▼</span></span>
<span class="line"><span> ┌────────────┐                   ┌────────────┐</span></span>
<span class="line"><span> │   parse    │ frontend          │    load    │ library</span></span>
<span class="line"><span> └─────┬──────┘                   └─────┬──────┘</span></span>
<span class="line"><span>       │ syntax tree                    │ declarations</span></span>
<span class="line"><span>       └────────────────┬───────────────┘</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span>                  ┌────────────┐</span></span>
<span class="line"><span>                  │   lower    │ semantic.lower</span></span>
<span class="line"><span>                  └─────┬──────┘</span></span>
<span class="line"><span>                        │ typed model</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span>                  ┌────────────┐</span></span>
<span class="line"><span>                  │  analyze   │ semantic.analysis</span></span>
<span class="line"><span>                  └─────┬──────┘</span></span>
<span class="line"><span>                        │ model and facts</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span>                  ┌────────────┐</span></span>
<span class="line"><span>                  │  validate  │ validation</span></span>
<span class="line"><span>                  └─────┬──────┘</span></span>
<span class="line"><span>                        │ validated model and facts</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span>                  ┌────────────┐</span></span>
<span class="line"><span>                  │    bind    │ targets</span></span>
<span class="line"><span>                  │   render   │</span></span>
<span class="line"><span>                  └─────┬──────┘</span></span>
<span class="line"><span>                        │ exact file bytes</span></span>
<span class="line"><span>                        ▼</span></span>
<span class="line"><span>                  ┌────────────┐</span></span>
<span class="line"><span>                  │   write    │ driver</span></span>
<span class="line"><span>                  └────────────┘</span></span></code></pre></div><p>Lowering resolves names, checks types, and normalizes the syntax tree. Analysis derives facts such as geometry, mass, connectivity, and action dataflow. Validation judges those facts without recomputing them or changing the model. Missing required facts produce diagnostics; optional unknowns remain visible. Validated values are immutable and retain their source locations.</p><p>The target binds actions and requirements to selected implementations. It checks unsupported operations and cross-file references before producing exact output bytes. The driver writes them only after planning succeeds and protects input files and unrelated output contents.</p><h2 id="dependency-direction" tabindex="-1">Dependency direction <a class="header-anchor" href="#dependency-direction" aria-label="Permalink to &quot;Dependency direction&quot;">​</a></h2><p>Each compiler package imports only the packages in its row, plus <code>support</code>, which holds diagnostics and source locations.</p><table tabindex="0"><thead><tr><th>Package</th><th>Imports</th></tr></thead><tbody><tr><td><code>cli</code></td><td><code>driver</code></td></tr><tr><td><code>driver</code></td><td>every package below</td></tr><tr><td><code>semantic.lower</code></td><td><code>frontend</code>, <code>library</code>, <code>semantic.model</code></td></tr><tr><td><code>semantic.analysis</code></td><td><code>semantic.model</code></td></tr><tr><td><code>validation</code></td><td><code>semantic.model</code></td></tr><tr><td><code>targets</code></td><td><code>semantic.model</code></td></tr><tr><td><code>frontend</code>, <code>library</code>, <code>semantic.model</code></td><td>nothing</td></tr></tbody></table><p>Inside <code>targets</code>, the simulator adapters (<code>gazebo</code>, <code>mujoco</code>) and the autonomy adapters (<code>ros2</code>, <code>nav2</code>) never import each other; a composing target (<code>ros_gz_nav2</code>, <code>ros_mujoco_nav2</code>) imports the ones it needs. The robot description is built by the Gazebo adapter and reused by the MuJoCo target without Gazebo&#39;s blocks. <code>targets/mission</code> (the mission and evaluation data every runtime reads) and <code>targets/payload</code> (the runtime files every target copies) are shared by the composing targets and imported by no adapter.</p><p>Lowering consumes the AST and already-loaded library declarations; the resolved model and its analyses do not depend on the parser. Frontend, semantic, and validation code do not import targets or perform file I/O. The driver loads source files and calls library loaders. Runtime helpers consume emitted data, not compiler models. URDF elements, plugins, topic names, and contact approximations belong in targets. Native-input adapters retain original files alongside their semantic projection.</p><p>Tests enforce import boundaries, compilation without ROS or simulator packages, and execution of generated output without the compiler checkout or installation.</p><h2 id="libraries-and-surrounding-projects" tabindex="-1">Libraries and surrounding projects <a class="header-anchor" href="#libraries-and-surrounding-projects" aria-label="Permalink to &quot;Libraries and surrounding projects&quot;">​</a></h2><p>Component and scene libraries are ordinary directories supplied explicitly at compile time. They contain declarations and local assets; they have no install step, package store, or hidden default location.</p><p>Acquisition, CAD conversion, image reconstruction, calibration, and policy training belong to external preparation tools. Original assets and official webpages stay with library source material. The experiment project owns cases, repetitions, acceptance thresholds, and aggregate scores.</p><h2 id="generated-output" tabindex="-1">Generated output <a class="header-anchor" href="#generated-output" aria-label="Permalink to &quot;Generated output&quot;">​</a></h2><p>Typed target models supply native consumers from the same resolved facts:</p><ul><li>Robot/world descriptions and their assets.</li><li>Controller, perception, and navigation configuration.</li><li>Executable task bindings, observation settings, and a launch entrypoint.</li><li>Diagnostics and optional inspection views, separate from execution inputs.</li></ul><p>Each executable responsibility has one authoritative representation. Runtime-facing formats are defined separately from internal compiler models. Shared values in different native formats are derived consistently. Output contains its required resources or explicitly binds resources supplied by the user&#39;s environment; it does not depend on the compiler checkout. Runtime logs and results stay outside the output.</p><p>Simulator and autonomy bindings are separate concerns. A new target implements the same semantic contracts and verifies actuation, sensors, timing, reset, and observations. Compilation checks the declared configuration; startup and execution establish whether the robot actually works.</p><p>See <a href="./language.html">Language</a> for semantics and <a href="./onboarding.html">Developer onboarding</a> for the development workflow.</p><h2 id="design-references" tabindex="-1">Design references <a class="header-anchor" href="#design-references" aria-label="Permalink to &quot;Design references&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reference</th><th>Principle used here</th></tr></thead><tbody><tr><td><a href="https://rustc-dev-guide.rust-lang.org/overview.html" target="_blank" rel="noreferrer">rustc</a></td><td>Separate syntax, semantic representations, analysis, and code generation.</td></tr><tr><td><a href="https://rust-analyzer.github.io/book/contributing/architecture.html" target="_blank" rel="noreferrer">rust-analyzer</a></td><td>Isolate semantic analysis from I/O and internal models from external formats.</td></tr><tr><td><a href="https://typespec.io/docs/extending-typespec/emitters-basics/" target="_blank" rel="noreferrer">TypeSpec</a></td><td>Emit different formats from one checked semantic model.</td></tr><tr><td><a href="https://mlir.llvm.org/docs/PassManagement/" target="_blank" rel="noreferrer">MLIR</a></td><td>Verify the model after every transformation stage; each stage receives valid input.</td></tr><tr><td><a href="https://github.com/Scenic-Foundation/Scenic/blob/main/src/scenic/core/simulators.py" target="_blank" rel="noreferrer">Scenic</a></td><td>Give simulator adapters explicit action and observation boundaries; one scenario language runs on CARLA, Webots, and other simulators.</td></tr><tr><td><a href="https://github.com/google-deepmind/mujoco_menagerie/blob/main/test/model_dir_test.py" target="_blank" rel="noreferrer">Menagerie</a></td><td>Require documentation, a license, and a changelog next to every library asset, and test for them.</td></tr></tbody></table><p>These are design references; none is a compiler dependency.</p>`,27)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
